('profile', '{"name":"Khun Thaw Zin Htun","title":"IT Support Specialist","tagline":"I build my own tools and take on client work.","location":"Yangon, Myanmar","email":"hello@example.com","github":"","telegram":""}'),
('about', '{"heading":"About","body":"I spent two years as an IT help desk technician at a systems integrator. Level 1 and Level 2 support, troubleshooting devices, talking to vendors. Firewalls, switches, routers, CCTV, VMware servers, Active Directory.\n\nOn my own I took on bigger things. I upgraded our Redmine ticketing system myself and migrated every ticket without losing one. I rebuilt our working hour management system into a much better version.\n\nNow I build software the same way I fixed systems. I design the tool, direct AI assistants to build it, test every part myself, and ship it. This site and the Android app in my projects were both built that way.\n\nI take on IT support and automation work."}'),
('skills', '{"categories":[{"name":"IT Support","items":["Help desk L1 and L2","Device troubleshooting","Vendor coordination","Redmine ticketing"]},{"name":"Infrastructure","items":["Firewalls, switches, routers","CCTV systems","VMware ESXi","Virtual servers","Active Directory"]},{"name":"AI-assisted development","items":["Directing AI coding agents","Python and PowerShell automation","Cloudflare (Tunnels, Pages, Workers, D1)","MCP servers","Shipping Android apps"]}]}'),
('projects', '[{"title":"Veil Reader","description":"A private Android reader for manga and manhwa. History, bookmarks, and reading progress stay on the phone and nowhere else. Tracker blocking, HTTPS-only browsing, and volume keys turn the pages.","tech":["Android","Kotlin","Privacy"],"link":""},{"title":"Nazarick Bridge","description":"My own server that lets AI assistants run tasks on my Windows machine. A local daemon does the work, a Cloudflare tunnel carries it out, and a health check proves it is alive.","tech":["Python","MCP","Cloudflare Tunnel"],"link":""},{"title":"Redmine Upgrade","description":"Upgraded the company Redmine ticketing system on my own. Migrated every ticket and record to the new version without losing anything.","tech":["Redmine","Data migration"],"link":""},{"title":"Working Hours Rebuild","description":"Took the company working hour management system and rebuilt it into a much better version for staff to track their hours.","tech":["PHP","Redesign"],"link":""}]'),
('experience', '[{"role":"IT Help Desk Service Technician","org":"Systems integrator","period":"Two years, until October 2026","points":["Level 1 and Level 2 support, troubleshooting IT devices, vendor communications.","Upgraded the Redmine ticketing system alone and migrated all data without loss.","Rebuilt the working hour management system into a much better version.","Hands-on with firewalls, switches, routers, CCTV, VMware ESXi, and Active Directory."]}]'),
